def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
    for max_cnt in a:
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for k in range(1, m + 1):
            prefix[k] = (prefix[k - 1] + dp[k]) % MOD
        new_dp = [0] * (m + 1)
        for k in range(m + 1):
            low = k - max_cnt - 1
            if low >= 0:
